// Writes packages/web/site/m3-scheme.ts: the M3 colour scheme of the aphrody-identity seed, generated by the
// canonical @aphrody/m3-tokens owner (m3SchemeCss of @aphrody/bun-plugin-tailwind). The site serves it inside
// /assets/site.css, so its colours do not depend on cdn.aphrody.com.
//
//   bun scripts/aphrody/brand-scheme.ts [--check]
import { resolve } from "node:path";
import { m3SchemeCss } from "../../packages/bun-plugin-tailwind/src/m3.ts";

export const BRAND_SEED = "#e2dbad";
const target = resolve(import.meta.dir, "../../packages/web/site/m3-scheme.ts");

export async function brandSchemeModule(seed = BRAND_SEED): Promise<string> {
  const css = (await m3SchemeCss(seed))
    .replace(/\s*\n\s*/g, "")
    .replace(/:\s+/g, ":")
    .replace(/\s*\{\s*/g, "{")
    .replace(/;\s*\}/g, "}");
  return `// Generated by m3SchemeCss("${seed}") (packages/bun-plugin-tailwind/src/m3.ts, @aphrody/m3-tokens): the M3 tonal-spot
// scheme of the aphrody-identity seed, served inside /assets/site.css instead of cdn.aphrody.com. Regenerate it with
// bun scripts/aphrody/brand-scheme.ts.
export const M3_SEED = "${seed}";
export const M3_SCHEME_CSS = ${JSON.stringify(css)};
`;
}

if (import.meta.main) {
  const next = await brandSchemeModule();
  const current = await Bun.file(target)
    .text()
    .catch(() => "");
  if (process.argv.includes("--check")) {
    if (current !== next) {
      console.error(`${target} differs from the generated scheme`);
      process.exit(1);
    }
  } else if (current !== next) await Bun.write(target, next);
}
